  duelIntro: { ro: "AI-ul îți aruncă afirmații despre anatomie. Unele sunt corecte, altele au erori subtile. Decide rapid: ADEVĂRAT sau FALS?", en: "The AI throws anatomy statements at you. Some are correct, others have subtle errors. Decide fast: TRUE or FALSE?", fr: "L'IA t'envoie des affirmations d'anatomie. Certaines sont correctes, d'autres ont des erreurs subtiles. Décide vite : VRAI ou FAUX ?", de: "Die KI wirft dir Anatomie-Aussagen zu. Einige sind richtig, andere enthalten feine Fehler. Entscheide schnell: WAHR oder FALSCH?", es: "La IA te lanza afirmaciones de anatomía. Algunas son correctas, otras tienen errores sutiles. Decide rápido: ¿VERDADERO o FALSO?", hu: "A MI anatómiai állításokat dob feléd. Némelyik helyes, másokban apró hibák vannak. Dönts gyorsan: IGAZ vagy HAMIS?" },
  quizTimeUp: { ro: "Timp expirat!", en: "Time's up!", fr: "Temps écoulé !", de: "Zeit abgelaufen!", es: "¡Se acabó el tiempo!", hu: "Lejárt az idő!" },
  quizTimeoutMsg: { ro: "Ai eșuat testul — nu ai răspuns la timp.", en: "You failed the test — you didn't answer in time.", fr: "Tu as échoué au test — tu n'as pas répondu à temps.", de: "Du hast den Test nicht bestanden — du hast nicht rechtzeitig geantwortet.", es: "Has fallado el test — no respondiste a tiempo.", hu: "Megbuktál a teszten — nem válaszoltál időben." },
  quizEndPerfectT: { ro: "PERFECT!", en: "PERFECT!", fr: "PARFAIT !", de: "PERFEKT!", es: "¡PERFECTO!", hu: "TÖKÉLETES!" },
  quizEndPerfectM: { ro: "Anatomie la nivel de medic. Impresionant!", en: "Doctor-level anatomy. Impressive!", fr: "Anatomie niveau médecin. Impressionnant !", de: "Anatomie auf Arztniveau. Beeindruckend!", es: "Anatomía a nivel de médico. ¡Impresionante!", hu: "Orvosi szintű anatómia. Lenyűgöző!" },
  quizEndGoldT: { ro: "Aur!", en: "Gold!", fr: "Or !", de: "Gold!", es: "¡Oro!", hu: "Arany!" },
  quizEndGoldM: { ro: "Excelent! Cunoști scheletul ca pe podul palmei.", en: "Excellent! You know the skeleton like the back of your hand.", fr: "Excellent ! Tu connais le squelette comme ta poche.", de: "Ausgezeichnet! Du kennst das Skelett wie deine Westentasche.", es: "¡Excelente! Conoces el esqueleto como la palma de tu mano.", hu: "Kiváló! Úgy ismered a csontvázat, mint a tenyeredet." },
  quizEndSilverT: { ro: "Argint", en: "Silver", fr: "Argent", de: "Silber", es: "Plata", hu: "Ezüst" },
  quizEndSilverM: { ro: "Foarte bine! Mai e puțin până la perfecțiune.", en: "Very good! Almost perfect.", fr: "Très bien ! Presque parfait.", de: "Sehr gut! Fast perfekt.", es: "¡Muy bien! Casi perfecto.", hu: "Nagyon jó! Már csak egy kicsi van hátra a tökéletességig." },
  quizEndBronzeT: { ro: "Bronz", en: "Bronze", fr: "Bronze", de: "Bronze", es: "Bronce", hu: "Bronz" },
  quizEndBronzeM: { ro: "Nu rău. Mai exersează și vei stăpâni perfect.", en: "Not bad. Keep practicing and you'll master it.", fr: "Pas mal. Continue à t'entraîner et tu maîtriseras.", de: "Nicht schlecht. Übe weiter und du wirst es meistern.", es: "No está mal. Sigue practicando y lo dominarás.", hu: "Nem rossz. Gyakorolj tovább, és tökéletesen elsajátítod." },
  quizEndLowT: { ro: "Continuă să înveți!", en: "Keep learning!", fr: "Continue d'apprendre !", de: "Lerne weiter!", es: "¡Sigue aprendiendo!", hu: "Tanulj tovább!" },
  quizEndLowM: { ro: "Studiază modelul 3D și revino. Reușești!", en: "Study the 3D model and come back. You've got this!", fr: "Étudie le modèle 3D et reviens. Tu vas y arriver !", de: "Studiere das 3D-Modell und komm zurück. Du schaffst das!", es: "Estudia el modelo 3D y vuelve. ¡Tú puedes!", hu: "Tanulmányozd a 3D-modellt, és gyere vissza. Menni fog!" },
  quizBadgeNew: { ro: "Insignă nouă:", en: "New badge:", fr: "Nouveau badge :", de: "Neues Abzeichen:", es: "Nueva insignia:", hu: "Új jelvény:" },
  quizBadgeUnlocked: { ro: "Ai deblocat o insignă nouă! O găsești în secțiunea Profil → Insignele mele.", en: "You unlocked a new badge! Find it in Profile → My badges.", fr: "Tu as débloqué un nouveau badge ! Retrouve-le dans Profil → Mes badges.", de: "Du hast ein neues Abzeichen freigeschaltet! Du findest es unter Profil → Meine Abzeichen.", es: "¡Has desbloqueado una nueva insignia! La encuentras en Perfil → Mis insignias.", hu: "Új jelvényt oldottál fel! Megtalálod a Profil → Jelvényeim részben." },
